# Fix the iteration over marker rows
from collections import deque, defaultdict

visited = set()

def bfs(start_r, start_c):
    comp = [(start_r, start_c)]
    q = deque([(start_r, start_c)])
    visited.add((start_r, start_c))
    while q:
        cr, cc = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = cr+dr, cc+dc
            if 0 <= nr < 17 and 0 <= nc < 21:
                if (nr, nc) not in visited and grid[nr][nc] != 0:
                    visited.add((nr, nc))
                    comp.append((nr, nc))
                    q.append((nr, nc))
    return comp

all_non_marker_cells = []
marker_rows = [1, 5, 10, 15, 16]
for r in range(17):
    for c in range(21):
        val = grid[r][c]
        if val == 0: continue
        if r == 0: continue
        if r in marker_rows and c == 0: continue
        all_non_marker_cells.append((r, c, val))

component_sets = []
for r, c, val in all_non_marker_cells:
    key = (r, c)
    found = False
    for i, comp in enumerate(component_sets):
        if key in comp:
            found = True
            break
    if not found:
        comp = bfs(r, c)
        component_sets.append(comp)

color_groups = defaultdict(list)
for i, comp in enumerate(component_sets):
    orig_color = grid[comp[0][0]][comp[0][1]]
    color_groups[orig_color].append(i)

markers = [(1, 4), (5, 1), (10, 9), (15, 6), (16, 2)]
comp_new_colors = {}

for color, comp_indices in sorted(color_groups.items()):
    rep_comp = component_sets[comp_indices[0]]
    avg_r = sum(r for r,c in rep_comp)/len(rep_comp)
    distances = []
    for mr, mval in markers:
        dist = abs(avg_r - mr)
        distances.append((dist, mr, mval))
    distances.sort(key=lambda x: (x[0], x[1]))
    best = distances[0]

    target_val = best[2]
    for idx in comp_indices:
        comp_new_colors[idx] = target_val

new_grid = [[0]*21 for _ in range(17)]
for i, comp in enumerate(component_sets):
    new_color = comp_new_colors[i]
    for r, c in comp:
        new_grid[r][c] = new_color

